1	-- Member age attestations for Studio programs that may be used by students (College Essay).
2	--
3	-- Founder ruling 2026-11-16 (recorded on #1900 and #1938), verbatim:
4	--   "if minors are using they must check off that they are under adult supervision."
5	--   "Yes, block under 13"  (reply to: under-13s turned away; 13–17 allowed after the adult-supervision check)
6	--
7	-- What this stores: the member's own attestation, by their own act at the program door:
8	--   'adult'  — they are 18 or older;
9	--   'minor'  — they are 13–17 AND they ticked that a parent, guardian or teacher is supervising (always true for 'minor').
10	-- ⛔ Nothing is ever stored for someone who says they are under 13: there is no row shape for it. They are turned away.
11	-- ⛔ Never writing, never a birth date, never inferred. Self-attested; not verification.
12	--
13	-- Shape: append-only (as writers_studio_beta_grant_events). A member's standing is their latest row. Erasing a member
14	-- removes their attestations with them (R20, ON DELETE CASCADE).
15	BEGIN;
16	SET LOCAL lock_timeout = '5s';
17	
18	CREATE TABLE IF NOT EXISTS member_age_attestations (
19	  id                    BIGSERIAL   PRIMARY KEY,
20	  member_id             UUID        NOT NULL REFERENCES members(id) ON DELETE CASCADE,
21	  age_band              TEXT        NOT NULL CHECK (age_band IN ('adult', 'minor')),
22	  supervision_attested  BOOLEAN     NOT NULL,
23	  -- The program door where it was given (a registered Studio program id), for the record only.
24	  studio_path           TEXT        CHECK (studio_path IS NULL OR studio_path ~ '^[a-z][a-z0-9-]{0,39}$'),
25	  attested_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
26	  -- A minor's attestation always carries the supervision tick; an adult's never needs one.
27	  CONSTRAINT member_age_attestations_minor_supervised CHECK (age_band <> 'minor' OR supervision_attested)
28	);
29	
30	CREATE INDEX IF NOT EXISTS idx_member_age_attestations_member_latest
31	  ON member_age_attestations (member_id, id DESC);
32	
33	-- Append-only: an attestation is never edited, and is removed only with its member.
34	CREATE OR REPLACE FUNCTION member_age_attestations_guard()
35	RETURNS trigger LANGUAGE plpgsql AS $$
36	BEGIN
37	  IF TG_OP = 'UPDATE' THEN
38	    RAISE EXCEPTION 'member_age_attestations is append-only';
39	  END IF;
40	  IF EXISTS (SELECT 1 FROM members WHERE id = OLD.member_id) THEN
41	    RAISE EXCEPTION 'member_age_attestations rows are removed only with their member';
42	  END IF;
43	  RETURN OLD;
44	END;
45	$$;
46	
47	DROP TRIGGER IF EXISTS member_age_attestations_guard ON member_age_attestations;
48	CREATE TRIGGER member_age_attestations_guard
49	  BEFORE UPDATE OR DELETE ON member_age_attestations
50	  FOR EACH ROW EXECUTE FUNCTION member_age_attestations_guard();
51	
52	CREATE OR REPLACE FUNCTION member_age_attestations_no_truncate()
53	RETURNS trigger LANGUAGE plpgsql AS $$
54	BEGIN
55	  RAISE EXCEPTION 'member_age_attestations may not be truncated';
56	END;
57	$$;
58	
59	DROP TRIGGER IF EXISTS member_age_attestations_no_truncate ON member_age_attestations;
60	CREATE TRIGGER member_age_attestations_no_truncate
61	  BEFORE TRUNCATE ON member_age_attestations
62	  FOR EACH STATEMENT EXECUTE FUNCTION member_age_attestations_no_truncate();
63	
64	COMMENT ON TABLE member_age_attestations IS
65	  'Self-attested age band at a Studio program door (founder ruling 2026-11-16, #1900): adult, or minor with adult supervision. Nothing stored for under-13 (turned away). Append-only.';
66	
67	COMMIT;
68

