1	// Production web requires force-dynamic for runtime database access (the pilot check).
2	// Capacitor builds: API routes are moved aside by scripts/build-capacitor.sh
3	export const dynamic = 'force-dynamic';
4	
5	/**
6	 * Writer's Studio — the Spark door's reflection (JARVIS-WRITERS-STUDIO-INSPIRATION-OPENING-01 · S1).
7	 *
8	 * POST { answer, history?, sanctuary? } → { reply }
9	 *
10	 * ⭐ Founder ruling Q1 (2026-11-11): the opening conversation is NEVER kept, in Ordinary or Sanctuary. This route
11	 * answers in the moment and writes nothing: no thread, no turn, no log of the writer's words. The only thing from the
12	 * opening that can ever be kept is a spark the writer chooses to hold, and that goes through the existing member-act
13	 * PATCH on their Work, never through here. Falsifier F7 pins the imports, so a store cannot be added quietly.
14	 *
15	 * ⭐ One mind: the reply comes from askMaia with the opt-in `arrival` context, the same path and provider seam as the
16	 * Work conversation (F8). Pilot-gated like the rest of the Studio's server surface (F10).
17	 */
18	import { NextRequest, NextResponse } from 'next/server';
19	import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
20	import { admittedToStudio, writersStudioStanding } from '@/lib/writersStudio/betaAccessServer';
21	import { askMaia } from '@/lib/manuscript/ask/askReader';
22	import { MAX_FIRST_PAGE_CHARS, quotesVerified } from '@/lib/writersStudio/inspirationOpening';
23	import { pathFromParam } from '@/lib/writersStudio/studioPaths';
24	import { ageAttestationAdmits, latestAgeAttestation } from '@/lib/studios/ageAttestationRead';
25	
26	const MAX_ANSWER_CHARS = 2000;
27	const MAX_HISTORY_TURNS = 20;
28	const MAX_HISTORY_CHARS = 4000;
29	const privateHeaders = { 'Cache-Control': 'private, no-store' };
30	
31	type Turn = { speaker: 'author' | 'maia'; body: string };
32	
33	function historyFrom(value: unknown): Turn[] | null {
34	  if (value === undefined) return [];
35	  if (!Array.isArray(value) || value.length > MAX_HISTORY_TURNS) return null;
36	  const turns: Turn[] = [];
37	  for (const item of value) {
38	    if (!item || typeof item !== 'object') return null;
39	    const { speaker, body } = item as Record<string, unknown>;
40	    if ((speaker !== 'author' && speaker !== 'maia') || typeof body !== 'string' || !body.trim() || body.length > MAX_HISTORY_CHARS) {
41	      return null;
42	    }
43	    turns.push({ speaker, body });
44	  }
45	  return turns;
46	}
47	
48	export async function POST(req: NextRequest) {
49	  if (process.env.CAPACITOR_BUILD) {
50	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
51	  }
52	  const memberId = await getMemberIdFromRequest(req);
53	  if (!memberId) return NextResponse.json({ error: 'unauthenticated' }, { status: 401, headers: privateHeaders });
54	  const access = await writersStudioStanding(memberId);
55	  if (!admittedToStudio(access)) return NextResponse.json({ refusal: 'not_in_beta_pilot' }, { status: 403, headers: privateHeaders });
56	
57	  let raw: unknown;
58	  try {
59	    raw = await req.json();
60	  } catch {
61	    return NextResponse.json({ refusal: 'malformed' }, { status: 400, headers: privateHeaders });
62	  }
63	  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
64	    return NextResponse.json({ refusal: 'malformed' }, { status: 400, headers: privateHeaders });
65	  }
66	  const body = raw as Record<string, unknown>;
67	  const allowed = new Set(['answer', 'history', 'sanctuary', 'moment', 'path']);
68	  if (Object.keys(body).some((key) => !allowed.has(key))) {
