82	/** The five stage words a member may claim. Orientation, never progress. */
83	const STAGES = ['capturing', 'developing', 'writing', 'refining', 'sharing'] as const;
84	
85	export async function PATCH(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
86	  if (process.env.CAPACITOR_BUILD) {
87	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
88	  }
89	  const { id } = await ctx.params;
90	
91	  if (process.env.MAIA_CABIN_MODE === 'offline') {
92	    const store = cabinStore();
93	    try {
94	      const { member, issuedToken } = cabinMemberFromRequest(store, request);
95	      const body = (await request.json().catch(() => ({}))) as {
96	        title?: unknown;
97	        purpose?: unknown;
98	        form?: unknown;
99	        stage?: unknown;
100	        manuscriptState?: unknown;
101	      };
102	
103	      const patch: Record<string, string | null> = {};
104	      for (const key of ['title', 'purpose', 'form', 'stage', 'manuscriptState']) {
105	        if (Object.prototype.hasOwnProperty.call(body, key)) {
106	          const value = body[key as keyof typeof body];
107	          if (value !== null && typeof value !== 'string') {
108	            return NextResponse.json({ error: key + ' must be text' }, { status: 400 });
