110	          patch[key] = value as string | null;
111	        }
112	      }
113	
114	      if (Object.keys(patch).length === 0) {
115	        return NextResponse.json({ error: 'nothing to change' }, { status: 400 });
116	      }
117	
118	      const work = store.updateWork(member.id, id, patch);
119	      if (!work) return NextResponse.json({ error: 'Not found' }, { status: 404 });
120	
121	      const response = NextResponse.json({
122	        work: {
123	          id: work.id,
124	          title: work.title,
125	          purpose: work.purpose,
126	          form: work.form,
127	          stage: work.stage,
128	          manuscriptState: work.manuscriptState,
129	          createdAt: work.createdAt,
130	          updatedAt: work.updatedAt,
131	        },
132	      });
133	      setCabinSessionCookie(response, issuedToken);
134	      return response;
135	    } finally {
136	      store.close();
137	    }
138	  }
