140	  try {
141	    const memberId = await getMemberIdFromRequest(request);
142	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
143	
144	    const body = (await request.json().catch(() => ({}))) as {
145	      title?: unknown;
146	      purpose?: unknown;
147	      form?: unknown;
148	      stage?: unknown;
149	      manuscriptState?: unknown;
150	      maiaRevisionsPaused?: unknown;
151	      studioPath?: unknown;
152	    };
153	    if (!('title' in body) && !('purpose' in body) && !('form' in body) && !('stage' in body) && !('manuscriptState' in body)
154	        && !('maiaRevisionsPaused' in body) && !('studioPath' in body)) {
155	      return NextResponse.json({ error: 'nothing to change' }, { status: 400 });
156	    }
