301	      params.push(manuscriptState);
302	      sets.push(`manuscript_state = $${params.length}`);
303	    }
304	    if ('maiaRevisionsPaused' in body) {
305	      params.push(maiaRevisionsPaused);
306	      sets.push(`maia_revisions_paused = $${params.length}`);
307	    }
308	    if ('studioPath' in body) {
309	      params.push(studioPath);
310	      sets.push(`studio_path = $${params.length}`);
311	    }
312	
313	    // Member-scoped in the predicate, not after the fact: another member's id
314	    // cannot reach this row at all.
315	    const updated = await query<WorkRow>(
316	      `UPDATE living_works
