54	import { studioPathById } from '@/lib/writersStudio/studioPaths';
55	import { NextRequest, NextResponse } from 'next/server';
56	import { query, transaction } from '@/lib/db/postgres';
57	import { sweepVaultErasureQueue } from '@/lib/manuscript/source/eraseManuscript';
58	import { takeRecoveryCaptureLock, writeWorkDeletionRecord } from '@/lib/manuscript/source/workDeletionRecord';
59	import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
60	import { refuseTitle } from '@/lib/livingWork/domain';
61	import { cabinStore, cabinMemberFromRequest, setCabinSessionCookie } from '@/lib/cabin/request';
62	
63	const MAX_TITLE_CHARS = 300;
64	
65	interface WorkRow {
66	  id: string;
67	  title: string | null;
68	  purpose: string | null;
69	  form: string | null;
70	  stage: string | null;
71	  manuscript_state: string | null;
72	  maia_revisions_paused?: boolean;
73	  studio_path?: string | null;
74	  created_at: string;
75	  updated_at: string;
76	}
77	
78	const MAX_PURPOSE_CHARS = 2000;
79	const MAX_FORM_CHARS = 100;
80	
81	/** The five stage words a member may claim. Orientation, never progress. */
82	const STAGES = ['capturing', 'developing', 'writing', 'refining', 'sharing'] as const;
83	
84	export async function PATCH(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
85	  if (process.env.CAPACITOR_BUILD) {
86	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
87	  }
88	  const { id } = await ctx.params;
89	
90	  if (process.env.MAIA_CABIN_MODE === 'offline') {
91	    const store = cabinStore();
92	    try {
93	      const { member, issuedToken } = cabinMemberFromRequest(store, request);
94	      const body = (await request.json().catch(() => ({}))) as {
95	        title?: unknown;
96	        purpose?: unknown;
97	        form?: unknown;
98	        stage?: unknown;
99	        manuscriptState?: unknown;
100	      };
101	
102	      const patch: Record<string, string | null> = {};
103	      for (const key of ['title', 'purpose', 'form', 'stage', 'manuscriptState']) {
104	        if (Object.prototype.hasOwnProperty.call(body, key)) {
105	          const value = body[key as keyof typeof body];
106	          if (value !== null && typeof value !== 'string') {
107	            return NextResponse.json({ error: key + ' must be text' }, { status: 400 });
108	          }
109	          patch[key] = value as string | null;
110	        }
111	      }
112	
113	      if (Object.keys(patch).length === 0) {
114	        return NextResponse.json({ error: 'nothing to change' }, { status: 400 });
115	      }
116	
117	      const work = store.updateWork(member.id, id, patch);
118	      if (!work) return NextResponse.json({ error: 'Not found' }, { status: 404 });
119	
120	      const response = NextResponse.json({
121	        work: {
122	          id: work.id,
123	          title: work.title,
124	          purpose: work.purpose,
125	          form: work.form,
126	          stage: work.stage,
127	          manuscriptState: work.manuscriptState,
128	          createdAt: work.createdAt,
129	          updatedAt: work.updatedAt,
130	        },
131	      });
132	      setCabinSessionCookie(response, issuedToken);
133	      return response;
134	    } finally {
135	      store.close();
136	    }
137	  }
138	
139	  try {
140	    const memberId = await getMemberIdFromRequest(request);
141	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
142	
143	    const body = (await request.json().catch(() => ({}))) as {
144	      title?: unknown;
145	      purpose?: unknown;
146	      form?: unknown;
147	      stage?: unknown;
148	      manuscriptState?: unknown;
149	      maiaRevisionsPaused?: unknown;
150	      studioPath?: unknown;
151	    };
152	    if (!('title' in body) && !('purpose' in body) && !('form' in body) && !('stage' in body) && !('manuscriptState' in body)
153	        && !('maiaRevisionsPaused' in body) && !('studioPath' in body)) {
154	      return NextResponse.json({ error: 'nothing to change' }, { status: 400 });
155	    }
156	
157	    /* `null` is allowed on purpose: a member may un-name a work they named too
158	       early. Recognition can be withdrawn without withdrawing the work. */
159	    let title: string | null = null;
160	    if (body.title !== null && body.title !== undefined) {
161	      if (typeof body.title !== 'string') {
162	        return NextResponse.json({ error: 'title must be text' }, { status: 400 });
163	      }
164	      if (body.title.length > MAX_TITLE_CHARS) {
165	        return NextResponse.json(
166	          { error: `title is longer than ${MAX_TITLE_CHARS} characters` },
167	          { status: 400 }
168	        );
169	      }
170	      if (refuseTitle(body.title) === 'blank_title') {
171	        return NextResponse.json({ error: 'blank_title' }, { status: 400 });
172	      }
173	      title = body.title;
174	    }
175	
176	    /* Purpose (Work Home, Slice 6): the member's stated intention for the
177	       work. Same member-authored rules as title — NEVER_AUTHORED_BY_THE_SYSTEM
178	       lists purpose; the only writer is this member act. Null un-states it. */
179	    let purpose: string | null = null;
180	    if (body.purpose !== null && body.purpose !== undefined) {
181	      if (typeof body.purpose !== 'string') {
182	        return NextResponse.json({ error: 'purpose must be text' }, { status: 400 });
183	      }
184	      if (body.purpose.length > MAX_PURPOSE_CHARS) {
185	        return NextResponse.json(
186	          { error: `purpose is longer than ${MAX_PURPOSE_CHARS} characters` },
187	          { status: 400 }
188	        );
189	      }
190	      if (body.purpose.trim().length === 0) {
191	        return NextResponse.json({ error: 'blank_purpose' }, { status: 400 });
192	      }
193	      purpose = body.purpose;
194	    }
195	
196	    /* Form and stage (Slice 6e): member-declared, same precedent as title and
197	       purpose — the NEVER_AUTHORED_BY_THE_SYSTEM list governs authorship, not
198	       existence, and the only writer is this member act. Form is the member's
199	       own word ("Book", "Blog series"); stage is one of five canonical words
200	       and is orientation, never progress — the system never advances it. */
201	    let form: string | null = null;
202	    if (body.form !== null && body.form !== undefined) {
203	      if (typeof body.form !== 'string') {
204	        return NextResponse.json({ error: 'form must be text' }, { status: 400 });
205	      }
206	      if (body.form.length > MAX_FORM_CHARS) {
207	        return NextResponse.json(
208	          { error: `form is longer than ${MAX_FORM_CHARS} characters` },
209	          { status: 400 }
210	        );
211	      }
212	      if (body.form.trim().length === 0) {
213	        return NextResponse.json({ error: 'blank_form' }, { status: 400 });
214	      }
215	      form = body.form;
216	    }
217	
218	    let stage: string | null = null;
219	    if (body.stage !== null && body.stage !== undefined) {
220	      if (typeof body.stage !== 'string' || !(STAGES as readonly string[]).includes(body.stage)) {
221	        return NextResponse.json({ error: 'unknown_stage' }, { status: 400 });
222	      }
223	      stage = body.stage;
224	    }
225	
226	    const MANUSCRIPT_STATES = ['pre-manuscript', 'partial-manuscript', 'existing-manuscript'] as const;
227	    let manuscriptState: string | null = null;
228	    if (body.manuscriptState !== null && body.manuscriptState !== undefined) {
229	      if (
230	        typeof body.manuscriptState !== 'string'
231	        || !(MANUSCRIPT_STATES as readonly string[]).includes(body.manuscriptState)
232	      ) {
233	        return NextResponse.json({ error: 'unknown_manuscript_state' }, { status: 400 });
234	      }
235	      manuscriptState = body.manuscriptState;
236	    }
237	
238	    /* "MAIA asks, never rewrites" for this whole Work (founder authorization
239	       2026-11-13, ledger #1938). Member-declared like form and stage; the only
240	       writer is this member act. A strict boolean: anything else is refused,
241	       never coerced. */
242	    let maiaRevisionsPaused = false;
243	    if ('maiaRevisionsPaused' in body) {
244	      if (typeof body.maiaRevisionsPaused !== 'boolean') {
245	        return NextResponse.json({ error: 'maiaRevisionsPaused must be true or false' }, { status: 400 });
246	      }
247	      maiaRevisionsPaused = body.maiaRevisionsPaused;
248	    }
249	
250	    /* The Studio program (path) this Work belongs to (ledger #1938). CONTRACT:
251	       A Work's program is explicitly declared through an authenticated, authorized action by the member who owns that Work.
252	       The declaration must identify a registered program. Once established, the program is immutable. No title, invitation,
253	       system process, or inferred context may silently assign or change it. (Founder contract ACCEPT_F2_MEMBER_DECLARATION_ONCE_FIXED,
254	       2026-11-15; supersedes earlier "Begin-only" wording, including this migration's header. The contract is member authorization,
255	       not button provenance: existing session authorization and request-integrity protections apply, and the client submits an
256	       explicit program selection, never an inferred one.)
257	       Enforced here (owner-scoped Work, registered id only, set once: same id is a no-op, clear 400, change 409) and in
258	       the database (FK to studio_programs, fixed-once trigger). */
259	    let studioPath: string | null = null;
260	    if ('studioPath' in body) {
261	      if (typeof body.studioPath !== 'string' || studioPathById(body.studioPath) === null) {
262	        return NextResponse.json({ error: 'unknown_studio_path' }, { status: 400 });
263	      }
264	      studioPath = body.studioPath;
265	      const current = await query<{ studio_path: string | null }>(
266	        `SELECT studio_path FROM living_works WHERE id = $1 AND member_id = $2`, [id, memberId]);
267	      if (current.rows.length === 0) return NextResponse.json({ error: 'Not found' }, { status: 404 });
268	      const existing = current.rows[0].studio_path;
269	      if (existing !== null && existing !== studioPath) {
270	        return NextResponse.json({ error: 'studio_path_fixed' }, { status: 409 });
271	      }
272	    }
273	
274	    // Only the fields the member actually addressed change; COALESCE-style
275	    // partial updates would silently keep a value the member tried to clear.
276	    const sets: string[] = [];
277	    const params: unknown[] = [id, memberId];
278	    if ('title' in body) {
279	      params.push(title);
280	      sets.push(`title = $${params.length}`);
281	    }
282	    if ('purpose' in body) {
283	      params.push(purpose);
284	      sets.push(`purpose = $${params.length}`);
285	    }
286	    if ('form' in body) {
287	      params.push(form);
288	      sets.push(`form = $${params.length}`);
289	    }
290	    if ('stage' in body) {
291	      params.push(stage);
292	      sets.push(`stage = $${params.length}`);
293	    }
294	    if ('manuscriptState' in body) {
295	      params.push(manuscriptState);
296	      sets.push(`manuscript_state = $${params.length}`);
297	    }
298	    if ('maiaRevisionsPaused' in body) {
299	      params.push(maiaRevisionsPaused);
300	      sets.push(`maia_revisions_paused = $${params.length}`);
301	    }
302	    if ('studioPath' in body) {
303	      params.push(studioPath);
304	      sets.push(`studio_path = $${params.length}`);
305	    }
306	
307	    // Member-scoped in the predicate, not after the fact: another member's id
308	    // cannot reach this row at all.
309	    const updated = await query<WorkRow>(
310	      `UPDATE living_works
311	          SET ${sets.join(', ')}, updated_at = now()
312	        WHERE id = $1 AND member_id = $2
313	      RETURNING id, title, purpose, form, stage, manuscript_state, maia_revisions_paused, studio_path, created_at, updated_at`,
314	      params
315	    );
316	    if (updated.rows.length === 0) {
317	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
318	    }
319	    const r = updated.rows[0];
320	    return NextResponse.json({
321	      work: {
322	        id: r.id,
323	        title: r.title,
324	        purpose: r.purpose,
325	        form: r.form,
326	        stage: r.stage,
327	        manuscriptState: r.manuscript_state,
328	        maiaRevisionsPaused: r.maia_revisions_paused === true,
329	        studioPath: r.studio_path ?? null,
330	        createdAt: r.created_at,
331	        updatedAt: r.updated_at,
332	      },
333	    });
334	  } catch (error) {
335	    // A racing second program choice is refused by the database's fixed-once trigger: same answer as the pre-check.
336	    if ((error as { code?: string; message?: string })?.code === '23514'
337	        && String((error as { message?: string })?.message ?? '').includes('studio_path is fixed')) {
338	      return NextResponse.json({ error: 'studio_path_fixed' }, { status: 409 });
339	    }
340	    console.error('[living-works] name failed', error);
341	    return NextResponse.json({ error: 'Could not save that name' }, { status: 500 });
342	  }
343	}
