345	export async function DELETE(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
346	  if (process.env.CAPACITOR_BUILD) {
347	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
348	  }
349	
350	  const { id } = await ctx.params;
351	
352	  if (process.env.MAIA_CABIN_MODE === 'offline') {
353	    const store = cabinStore();
354	    try {
355	      const { member, issuedToken } = cabinMemberFromRequest(store, request);
356	      if (!store.deleteWork(member.id, id)) {
357	        return NextResponse.json({ error: 'Not found' }, { status: 404 });
358	      }
359	      const response = NextResponse.json({ withdrawn: id });
360	      setCabinSessionCookie(response, issuedToken);
361	      return response;
362	    } finally {
363	      store.close();
364	    }
365	  }
366	
367	  try {
368	    const memberId = await getMemberIdFromRequest(request);
369	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
370	
371	    /* One transaction, because a withdrawn Work's image must not outlive it.
372	       ON DELETE CASCADE takes the living_work_visuals ROW; it cannot take the
373	       bytes. Reading the path first and enqueueing it in the same transaction
374	       is what keeps the vault from accumulating images nothing can name — the
375	       *unreferenced but retained* state WS-DELETE-01 forbids, restated by the
376	       founder for Work visuals on 2026-09-07. */
377	    const removed = await transaction(async (tx) => {
378	      /* LOCK ORDER. eraseManuscript takes the recovery-capture advisory lock FIRST, then the Work row, then the image row afterwards, so
379	         this takes all three in the SAME order. Taking the Work row before the advisory lock, or the image row (the read below is FOR
380	         UPDATE) before the Work row, forms a real cycle with a Delete of the Work's writing: PostgreSQL breaks it by aborting one of the
381	         two with a 500 for an act that did not happen. The advisory lock is unconditional (it is taken even for an id that is not this
382	         member's), because a lock taken only after finding the row would come after a row lock on that path. It also means a Remove
383	         waits, with no timeout, while anything else holds the key: a writing Delete holds it for its whole transaction, and eraseManuscript.ts
384	         documents a coherent R20 backup as a holder too (no such backup caller is in this tree). A row that is not this member's, or is
385	         already gone, ends at the next statement (404) without writing anything. */
386	      await takeRecoveryCaptureLock(tx);
387	      const owned = await tx.query<{ id: string }>(
388	        `SELECT id FROM living_works WHERE id = $1 AND member_id = $2 FOR UPDATE`,
389	        [id, memberId],
390	      );
391	      if (owned.rows.length === 0) return null;
392	      const visual = await tx.query<{ storage_path: string }>(
393	        `SELECT storage_path FROM living_work_visuals WHERE living_work_id = $1 AND member_id = $2 FOR UPDATE`,
394	        [id, memberId],
395	      );
396	      const gone = await tx.query<{ id: string }>(
397	        `DELETE FROM living_works WHERE id = $1 AND member_id = $2 RETURNING id`,
398	        [id, memberId],
399	      );
400	      if (gone.rows.length === 0) return null;
401	
402	      /* The record of the removal, written only now that THIS statement really deleted the row (a lost race writes nothing), with the
403	         id the DELETE returned and not the one from the URL. Same transaction: if it cannot be written the Work is not removed. */
