1	// Production web requires force-dynamic for runtime database access (the pilot check).
2	// Capacitor builds: API routes are moved aside by scripts/build-capacitor.sh
3	export const dynamic = 'force-dynamic';
4	
5	/**
6	 * Writer's Studio — the Spark door's reflection (JARVIS-WRITERS-STUDIO-INSPIRATION-OPENING-01 · S1).
7	 *
8	 * POST { answer, history?, sanctuary? } → { reply }
9	 *
10	 * ⭐ Founder ruling Q1 (2026-11-11): the opening conversation is NEVER kept, in Ordinary or Sanctuary. This route
11	 * answers in the moment and writes nothing: no thread, no turn, no log of the writer's words. The only thing from the
12	 * opening that can ever be kept is a spark the writer chooses to hold, and that goes through the existing member-act
13	 * PATCH on their Work, never through here. Falsifier F7 pins the imports, so a store cannot be added quietly.
14	 *
15	 * ⭐ One mind: the reply comes from askMaia with the opt-in `arrival` context, the same path and provider seam as the
16	 * Work conversation (F8). Pilot-gated like the rest of the Studio's server surface (F10).
17	 */
18	import { NextRequest, NextResponse } from 'next/server';
19	import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
20	import { admittedToStudio, writersStudioStanding } from '@/lib/writersStudio/betaAccessServer';
21	import { askMaia } from '@/lib/manuscript/ask/askReader';
22	import { MAX_FIRST_PAGE_CHARS, quotesVerified } from '@/lib/writersStudio/inspirationOpening';
23	import { pathFromParam } from '@/lib/writersStudio/studioPaths';
24	
25	const MAX_ANSWER_CHARS = 2000;
26	const MAX_HISTORY_TURNS = 20;
27	const MAX_HISTORY_CHARS = 4000;
28	const privateHeaders = { 'Cache-Control': 'private, no-store' };
29	
30	type Turn = { speaker: 'author' | 'maia'; body: string };
31	
32	function historyFrom(value: unknown): Turn[] | null {
33	  if (value === undefined) return [];
34	  if (!Array.isArray(value) || value.length > MAX_HISTORY_TURNS) return null;
35	  const turns: Turn[] = [];
36	  for (const item of value) {
37	    if (!item || typeof item !== 'object') return null;
38	    const { speaker, body } = item as Record<string, unknown>;
39	    if ((speaker !== 'author' && speaker !== 'maia') || typeof body !== 'string' || !body.trim() || body.length > MAX_HISTORY_CHARS) {
40	      return null;
41	    }
42	    turns.push({ speaker, body });
43	  }
44	  return turns;
45	}
46	
47	export async function POST(req: NextRequest) {
48	  if (process.env.CAPACITOR_BUILD) {
49	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
50	  }
51	  const memberId = await getMemberIdFromRequest(req);
52	  if (!memberId) return NextResponse.json({ error: 'unauthenticated' }, { status: 401, headers: privateHeaders });
53	  const access = await writersStudioStanding(memberId);
54	  if (!admittedToStudio(access)) return NextResponse.json({ refusal: 'not_in_beta_pilot' }, { status: 403, headers: privateHeaders });
55	
56	  let raw: unknown;
57	  try {
58	    raw = await req.json();
59	  } catch {
60	    return NextResponse.json({ refusal: 'malformed' }, { status: 400, headers: privateHeaders });
61	  }
62	  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
63	    return NextResponse.json({ refusal: 'malformed' }, { status: 400, headers: privateHeaders });
64	  }
65	  const body = raw as Record<string, unknown>;
66	  const allowed = new Set(['answer', 'history', 'sanctuary', 'moment', 'path']);
67	  if (Object.keys(body).some((key) => !allowed.has(key))) {
68	    return NextResponse.json({ refusal: 'malformed', detail: 'unknown field' }, { status: 400, headers: privateHeaders });
69	  }
70	  if (body.moment !== undefined && body.moment !== 'spark' && body.moment !== 'first_page') {
71	    return NextResponse.json({ refusal: 'malformed', detail: 'moment' }, { status: 400, headers: privateHeaders });
72	  }
73	  // Studio paths (F17/F20): the member's own path, by exact id. Its frame is looked up server-side from the registry;
74	  // the request supplies only the id. An unknown path is refused, never quietly treated as the generic door.
75	  const studioPath = 'path' in body ? pathFromParam(typeof body.path === 'string' ? body.path : null) : null;
76	  if ('path' in body && (!studioPath || body.moment !== undefined)) {
77	    return NextResponse.json({ refusal: 'malformed', detail: 'path' }, { status: 400, headers: privateHeaders });
78	  }
